 {auto file=File::getCurrentWorkingDirectory().getChildFile("Tests/ImportedFX-v09-Final/SynthHacker Free Presets").findChildFiles(File::findFiles,true,"BA - Bertha.SerumPreset");if(file.isEmpty())return fail("pack state fixture missing");String error;if(!p.loadSerumPreset(file[0],file[0].getParentDirectory(),error))return fail("fixture load");auto original=std::atomic_load(&p.importedAssets);if(original->expansion->fx.size()!=4||original->expansion->fx[0].nativeType!=12||original->expansion->fxMods.empty())return fail("real split topology/mod parsing");auto old=std::make_shared<ImportedAssets>(*original);old->warnings.add("FX routing/frequency shift not reproduced: FXSplit");old->warnings.add("Unmapped modulation: FXHyperD / kParamDimEWet / source 2");std::atomic_store(&p.importedAssets,std::shared_ptr<const ImportedAssets>(old));MemoryBlock state;p.getStateInformation(state);p.loadPreset(0);p.setStateInformation(state.getData(),(int)state.getSize());auto restored=std::atomic_load(&p.importedAssets);if(!restored||restored->expansion->fx.size()!=4||restored->expansion->fxMods.size()!=original->expansion->fxMods.size())return fail("FX state recall");for(auto& warning:restored->warnings)if(warning.startsWith("FX routing/frequency shift not reproduced:")||warning.startsWith("Unmapped modulation: FXHyperD"))return fail("obsolete state warnings");ExpandedFx before,after;before.prepare(*original->expansion,48000,512,p.state);after.prepare(*restored->expansion,48000,512,p.state);for(int block=0;block<8;++block){auto a=source,b=source;before.process(a,0,512,settings);after.process(b,0,512,settings);for(int c=0;c<2;++c)for(int sample=0;sample<512;++sample)if(std::abs(a.getSample(c,sample)-b.getSample(c,sample))>1e-6)return fail("imported FX audio recall");}}
